4 | void quick_sort(long long *a, long long *b, long long n) {
5 | 
6 | 	int i, j, p, t;
7 | 	if (n < 2)
8 | 		return;
9 | 	p = a[n / 2];
10 | 	for (i = 0, j = n - 1;; i++, j--)
11 | 	{
12 | 		while (a[i] < p)
13 | 			i++;
14 | 		while (p < a[j])
15 | 			j--;
16 | 		if (i >= j)
17 | 			break;
