19 | 		a[i] = a[j];
20 | 		a[j] = t;
21 | 		t = b[i];
22 | 		b[i] = b[j];
23 | 		b[j] = t;
24 | 	}
25 | 	quick_sort(a, b, i);
26 | 	quick_sort(a + i, b + i, n - i);
27 | }
